    "contentId": "pf2e:bestiary:agents-of-edgewatch-bestiary:skitterstitch",
    "locale": "pt-BR",
    "sourceTranslatableHash": "sha256:1c72385da4b1a2d00c3b347f42c67b5e2a361cec8e1e610462e5b671108408f7",
    "version": 1,
